example.code:
@property --delta { syntax: "<integer>"; inherits: true; initial-value: 0; }

.score { --points: state(0); --delta: calc(var(--points) - previous(--points)); }
.score .current { text: var(--points); }
.score .prev    { text: previous(--points); }
.score .delta   { text: var(--delta); }
.score:when(direction(--points) > 0) .direction { text: "▲ up"; }

.stepper { --qty: state(1); }
.stepper .plus  { on: click(increment(--qty)); attr: disabled when(--qty >= 10); }
.stepper .minus { on: click(decrement(--qty)); attr: disabled when(--qty <= 1); }
.menu > button  { attr: aria-expanded var(--open); }

/* <span class="count">0</span> <span class="unit">items</span> */
.cart { --items: state(0); }
.cart .add:on(click) { --items: increment(1); }
.cart .count { content: var(--items); }
.cart .unit { content: when(--items == 1, "item", "items"); }

usage.code:
/* <h2 tabindex="-1"> in the HTML */
.wizard { --step: state(1); }
.wizard .panel > h2 { focus: false; }
.wizard .panel:nth-var(--step) > h2 { focus: true; }

.pc { --n: state(0, persist("visits", session)); }
.pc .inc:on(click) { --n: increment(1); }
.pc .v { content: var(--n); }

.pad { --x: state(0px); --y: state(0px); }
.pad:on(pointerdown) {
  --x: set(event(local-x));
  --y: set(event(local-y));
}
.pad .dot { translate: var(--x) var(--y); }

.slider { --v: state(0px); }
.slider .thumb {
  translate: var(--v) 0;
  touch-action: none;
}
.slider .thumb:on(drag) { --v: set(clamp(0px, event(x), 200px)); }
.slider .thumb:on(keydown(ArrowRight), prevent()) { --v: set(min(var(--v) + 10px, 200px)); }
.slider .thumb:on(keydown(ArrowLeft), prevent()) { --v: set(max(var(--v) - 10px, 0px)); }

example.code:
.dial { --level: state(5); }
.dial .reset:on(click) { --level: set(5); }
.dial .max:on(click) { --level: set(10); }
.dial .half:on(click) { --level: set(round(var(--level) / 2)); }
.dial .value { content: var(--level); }

/* <button class="speed">Speed <span class="value">1</span>×</button> */
.player { --speed: state(1); }
.player .speed:on(click) { --speed: cycle(1, 1.5, 2); }
.player .speed .value { content: var(--speed); }

.tab {
  on: click(set(--active, sibling-index(), closest(.tabs)));
}

.form input {
  bind: --name closest(.form);
}

@keyframes fade { to { opacity: 0; } }

.toast { --shown: state(true); }
.toast:when(--shown) { animation: fade 2s forwards; }
.toast { on: animationend(set(--shown, false)); }
.toast:when(not --shown) { display: none; }

input:just-checked + .icon {
  animation: check-in 300ms;
}

input:just-unchecked + .icon {
  animation: check-out 300ms;
}

@keyframes shake {
  25% { translate: -4px 0; }
  75% { translate: 4px 0; }
}

input:blur:invalid {
  animation: shake 250ms;
  outline: 2px solid orange;
}

.star {
  translate: random(0px, 400px) random(0px, 200px);
  rotate: random(-30deg, 30deg, 15deg);
}

.die { --face: state(1); }
.die:on(click) { --face: set(random(1, 6, 1)); }

/* wave() is removed. The native replacement: */
@property --y { syntax: "<length>"; inherits: false; initial-value: 0px; }
@keyframes y { from { --y: -8px; } to { --y: 8px; } }
.floating {
  translate: 0 var(--y);
  animation: y 1.5s ease-in-out infinite alternate;
}
